// Builds dist/data/boosters.js from the wiki booster pages (db/source/wiki_boosters.json),
// the game's own Korean (db/source/game_names_ko.json) and the site's detail lines
// (db/source/booster_korean.json). Do not edit the output.
// Usage: node scripts/build-boosters.mjs
import { readFile, writeFile } from 'node:fs/promises';
import { warbonds } from '../dist/data/warbonds.js';
import { boosterFacts, gameText } from './booster-parse.mjs';

const read = async name => JSON.parse(await readFile(new URL(`../db/source/${name}`, import.meta.url), 'utf8'));
const wiki = await read('wiki_boosters.json');
const korean = (await read('booster_korean.json')).boosters;
const game = await read('game_names_ko.json');
const warbondByName = new Map(warbonds.map(warbond => [warbond.en, warbond.id]));

const boosters = Object.entries(wiki.boosters).map(([id, page]) => {
  const text = korean[id];
  if (!text) throw new Error(`${id}: add it to db/source/booster_korean.json`);
  const facts = boosterFacts(page.text);
  const warbondId = warbondByName.get(facts.warbond);
  if (!warbondId) throw new Error(`${id}: warbond "${facts.warbond}" is not in warbonds.js`);
  const ko = key => {
    const value = game.strings.boosters[key];
    if (!value) throw new Error(`${id}: no game Korean for "${key}" (run scripts/tools/export-game-names.mjs)`);
    return value;
  };
  return {
    id, name: ko(text.name), en: page.title,
    description: text.description ? gameText(ko(text.description), text.value) : null,
    descriptionEn: text.description ? gameText(text.description, text.value) : null,
    detail: text.detail?.ko ?? null, detailEn: text.detail?.en ?? null,
    warbondId, page: facts.page, cost: facts.cost, order: facts.order,
    icon: { src: `./assets/boosters/${page.icon.file}`, source: page.icon.source, sha256: page.icon.sha256 },
    wiki: `https://helldivers.wiki.gg/wiki/${page.title.replaceAll(' ', '_')}`, revision: page.revision,
  };
}).sort((a, b) => a.order - b.order);

const out = `// Generated by scripts/build-boosters.mjs. Do not edit.
// Names and descriptions are the game's Korean (game build ${game.build}); detail lines
// summarize each wiki page. Icons are the wiki's original SVGs (CC BY-NC-SA 4.0).
export const boostersCheckedAt = ${JSON.stringify(wiki.retrievedAt)};
export const boostersGameBuild = ${JSON.stringify(game.build)};
export const boosters = ${JSON.stringify(boosters, null, 1)};
`;
await writeFile(new URL('../dist/data/boosters.js', import.meta.url), out);
console.log(`${boosters.length} boosters`);
